class Solution {
    public int leastOpsExpressTarget(int x, int target) {
        int pos = 0, cost = 0;
        int curCost = Integer.MAX_VALUE, nextCost = Integer.MAX_VALUE;
        curCost = 0; nextCost = 0;
        java.util.Map<Integer, Integer> memo = new java.util.HashMap<>();
        return dfs(x, target, 0, memo);
    }
    private int dfs(int x, int target, int pos, java.util.Map<Integer, Integer> memo) {
        if (target == 0) return 0;
        if (target < 0) return Integer.MAX_VALUE / 2;
        int key = target * 40 + pos;
        if (memo.containsKey(key)) return memo.get(key);
        long power = (long) Math.pow(x, pos);
        if (power > 2L * target) {
            int use = pos == 0 ? 2 * target : target * pos;
            int skip = pos == 0 ? 2 * (int)(x - target) : (int)(power - target) * pos;
            memo.put(key, Math.min(use, skip + pos));
            return memo.get(key);
        }
        int digit = (int)(target / power);
        int costPerDigit = pos == 0 ? 2 : pos;
        int useDigit = digit * costPerDigit + dfs(x, (int)(target - digit * power), pos + 1, memo);
        int roundUp = (x - digit) * costPerDigit + dfs(x, (int)((digit + 1) * power - target), pos + 1, memo);
        int res = Math.min(useDigit, roundUp) + (pos == 0 ? 0 : 0);
        memo.put(key, res);
        return res;
    }
}
